insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'TR', '{"original":"Türkiye Scholarships","en":"Türkiye Scholarships","ru":"Стипендия «Türkiye Burslari»"}'::jsonb, 'full', '{"en":"Government of Türkiye","ru":"Правительство Турции"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; usually covers tuition, accommodation and a monthly allowance. Check the official page for the countries, levels and the application window.","ru":"Для иностранных студентов; обычно покрывает обучение, проживание и ежемесячную стипендию. Страны, уровни и сроки подачи — на официальной странице."}'::jsonb, 'https://turkiyeburslari.gov.tr/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'HU', '{"original":"Stipendium Hungaricum","en":"Stipendium Hungaricum","ru":"Stipendium Hungaricum"}'::jsonb, 'full', '{"en":"Government of Hungary","ru":"Правительство Венгрии"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For students from partner countries; usually covers tuition and a monthly stipend, with accommodation support. Applications go through the national agency of your country.","ru":"Для студентов из стран-партнёров; обычно покрывает обучение и ежемесячную стипендию, помогает с жильём. Заявки подаются через ведомство вашей страны."}'::jsonb, 'https://stipendiumhungaricum.hu/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'DE', '{"original":"DAAD scholarships","en":"DAAD scholarships","ru":"Стипендии DAAD"}'::jsonb, 'partial', '{"en":"German Academic Exchange Service (DAAD)","ru":"Германская служба академических обменов (DAAD)"}'::jsonb, array['master', 'phd']::text[], '{"en":"Many programmes for different countries and levels; the DAAD scholarship database shows the ones open to you.","ru":"Много программ для разных стран и уровней; база стипендий DAAD показывает те, что доступны вам."}'::jsonb, 'https://www.daad.de/en/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'PL', '{"original":"NAWA scholarships","en":"NAWA scholarships","ru":"Стипендии NAWA"}'::jsonb, 'partial', '{"en":"Polish National Agency for Academic Exchange (NAWA)","ru":"Национальное агентство академических обменов Польши (NAWA)"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Several programmes for foreign students and researchers; the conditions differ by programme.","ru":"Несколько программ для иностранных студентов и исследователей; условия зависят от программы."}'::jsonb, 'https://nawa.gov.pl/en', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'CN', '{"original":"Chinese Government Scholarship (CSC)","en":"Chinese Government Scholarship (CSC)","ru":"Правительственная стипендия Китая (CSC)"}'::jsonb, 'full', '{"en":"China Scholarship Council","ru":"Китайский стипендиальный совет"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; the types differ in what they cover. Applications and deadlines are on the official portal.","ru":"Для иностранных студентов; разные типы покрывают разные расходы. Заявки и сроки — на официальном портале."}'::jsonb, 'https://www.campuschina.org/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'KR', '{"original":"Global Korea Scholarship (GKS)","en":"Global Korea Scholarship (GKS)","ru":"Global Korea Scholarship (GKS)"}'::jsonb, 'full', '{"en":"Government of the Republic of Korea","ru":"Правительство Республики Корея"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For international students; covers tuition and a living allowance. Applications through the Korean embassy or a chosen university.","ru":"Для иностранных студентов; покрывает обучение и проживание. Заявки — через посольство Кореи или выбранный университет."}'::jsonb, 'https://www.studyinkorea.go.kr/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'JP', '{"original":"MEXT scholarship","en":"MEXT scholarship","ru":"Стипендия MEXT"}'::jsonb, 'full', '{"en":"Ministry of Education (MEXT), Japan","ru":"Министерство образования Японии (MEXT)"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Japanese Government scholarship for international students; the application route is through the Japanese embassy or a university.","ru":"Стипендия правительства Японии для иностранцев; заявки — через посольство Японии или университет."}'::jsonb, 'https://www.studyinjapan.go.jp/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'FR', '{"original":"Eiffel Excellence Scholarship","en":"Eiffel Excellence Scholarship","ru":"Стипендия Эйфеля (Eiffel Excellence)"}'::jsonb, 'living', '{"en":"French Ministry for Europe and Foreign Affairs","ru":"Министерство Европы и иностранных дел Франции"}'::jsonb, array['master', 'phd']::text[], '{"en":"For master''s and PhD students; the application is made by the French institution, not by the student.","ru":"Для магистров и докторантов; заявку подаёт французское учебное заведение, а не студент."}'::jsonb, 'https://www.campusfrance.org/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'RU', '{"original":"Russian Government Scholarship (quota)","en":"Russian Government Scholarship (quota)","ru":"Квота правительства России на бесплатное обучение"}'::jsonb, 'full', '{"en":"Government of the Russian Federation","ru":"Правительство Российской Федерации"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Free places in Russian universities for foreign citizens; the application is made on the official portal.","ru":"Бесплатные места в российских вузах для иностранных граждан; заявка подаётся на официальном портале."}'::jsonb, 'https://education-in-russia.com/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'GB', '{"original":"Chevening Scholarships","en":"Chevening Scholarships","ru":"Стипендии Chevening"}'::jsonb, 'full', '{"en":"UK Government (FCDO)","ru":"Правительство Великобритании (FCDO)"}'::jsonb, array['master']::text[], '{"en":"One-year master''s in the UK for future leaders from eligible countries; work experience is required.","ru":"Годичная магистратура в Великобритании для будущих лидеров из подходящих стран; нужен опыт работы."}'::jsonb, 'https://www.chevening.org/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'US', '{"original":"Fulbright Foreign Student Program","en":"Fulbright Foreign Student Program","ru":"Программа Фулбрайта для иностранных студентов"}'::jsonb, 'full', '{"en":"US Department of State","ru":"Госдепартамент США"}'::jsonb, array['master', 'phd']::text[], '{"en":"Graduate study in the USA; applications go through the Fulbright commission or the US embassy of your country.","ru":"Обучение в магистратуре и аспирантуре США; заявки — через комиссию Фулбрайта или посольство США в вашей стране."}'::jsonb, 'https://foreign.fulbrightonline.org/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'AU', '{"original":"Australia Awards","en":"Australia Awards","ru":"Australia Awards"}'::jsonb, 'full', '{"en":"Australian Government","ru":"Правительство Австралии"}'::jsonb, array['master', 'phd']::text[], '{"en":"Postgraduate scholarships for people from eligible countries; check the official page for your country.","ru":"Стипендии для магистратуры и аспирантуры для жителей подходящих стран; свою страну проверьте на официальной странице."}'::jsonb, 'https://www.dfat.gov.au/people-to-people/australia-awards', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', null, '{"original":"Erasmus Mundus Joint Masters","en":"Erasmus Mundus Joint Masters","ru":"Erasmus Mundus (совместные магистерские программы)"}'::jsonb, 'full', '{"en":"European Union","ru":"Европейский союз"}'::jsonb, array['master']::text[], '{"en":"Joint master''s programmes in several European countries; scholarships are given by the programme itself, apply on the programme''s website.","ru":"Совместные магистерские программы в нескольких странах Европы; стипендии выдаёт сама программа, заявка — на её сайте."}'::jsonb, 'https://erasmus-plus.ec.europa.eu/', 'published', now(), '2026-10-07', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'NL', '{"original":"NL Scholarship (formerly Holland Scholarship)","en":"NL Scholarship (formerly Holland Scholarship)","ru":"Стипендия NL (бывшая Holland Scholarship)"}'::jsonb, 'partial', '{"en":"Nuffic and the participating Dutch institutions","ru":"Nuffic и участвующие нидерландские вузы"}'::jsonb, array['bachelor', 'master']::text[], '{"en":"For students from outside the EEA who start a full-time bachelor''s or master''s programme at a participating Dutch institution and do not already hold a degree from a Dutch institution. The amount and the list of institutions are on the official page.","ru":"Для студентов из стран вне ЕЭЗ, которые начинают очную программу бакалавриата или магистратуры в участвующем нидерландском вузе и ещё не имеют диплома нидерландского вуза. Сумма и список вузов — на официальной странице."}'::jsonb, 'https://www.studyinnl.org/finances/nl-scholarship', 'published', now(), '2026-10-23', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'CH', '{"original":"Swiss Government Excellence Scholarships","en":"Swiss Government Excellence Scholarships","ru":"Стипендии правительства Швейцарии (Excellence Scholarships)"}'::jsonb, 'living', '{"en":"Swiss State Secretariat for Education, Research and Innovation (SERI)","ru":"Государственный секретариат Швейцарии по образованию, исследованиям и инновациям (SERI)"}'::jsonb, array['master', 'phd']::text[], '{"en":"Mainly for early-career researchers who already hold a master''s degree (doctoral research), and for first master''s studies in an artistic field. Open to applicants from 183 countries; every application needs the support of a professor at a Swiss institution. Applications go through Swiss diplomatic representations.","ru":"В основном для молодых исследователей, у которых уже есть магистерская степень (докторские исследования), а также для первой магистратуры в области искусства. Открыты для заявителей из 183 стран; для каждой заявки нужна поддержка профессора швейцарского вуза. Заявки подаются через дипломатические представительства Швейцарии."}'::jsonb, 'https://www.sbfi.admin.ch/en/swiss-government-excellence-scholarships', 'published', now(), '2026-10-23', null);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', null, '{"original":"Visegrad Scholarship Programme","en":"Visegrad Scholarship Programme","ru":"Стипендиальная программа Вышеградского фонда"}'::jsonb, 'partial', '{"en":"International Visegrad Fund","ru":"Международный Вышеградский фонд"}'::jsonb, array['master', 'phd']::text[], '{"en":"Master''s and post-master''s study or research for 1-2 semesters in Czechia, Hungary, Poland or Slovakia. Citizens of the Eastern Partnership and Western Balkans countries listed on the official page can apply; you cannot study in your own country of citizenship. The list of countries and the amounts are on the official page.","ru":"Обучение или исследование в магистратуре и после неё на 1–2 семестра в Чехии, Венгрии, Польше или Словакии. Подать заявку могут граждане стран Восточного партнёрства и Западных Балкан, указанных на официальной странице; учиться в стране своего гражданства нельзя. Список стран и суммы — на официальной странице."}'::jsonb, 'https://www.visegradfund.org/apply/mobilities/visegrad-scholarships/', 'published', now(), '2026-10-23', array['AL', 'AM', 'AZ', 'BA', 'BY', 'GE', 'MD', 'ME', 'MK', 'RS', 'UA']::text[]);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'KZ', '{"original":"Bolashak International Scholarship","en":"Bolashak International Scholarship","ru":"Международная стипендия «Болашак»"}'::jsonb, null, '{"en":"Government of Kazakhstan","ru":"Правительство Казахстана"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"For citizens of Kazakhstan who study abroad (bachelor''s, master''s, doctoral level) or do scientific internships. It is awarded once for each level; independent master''s applicants need an offer from a university on the list of recommended universities. Check the official page for the current competition.","ru":"Для граждан Казахстана, которые учатся за границей (бакалавриат, магистратура, докторантура) или проходят научные стажировки. Присуждается один раз на каждый уровень; для магистрантов-«самостоятельных» нужно приглашение вуза из перечня рекомендуемых. Условия текущего конкурса — на официальной странице."}'::jsonb, 'https://bolashak.gov.kz/en/scholarship-program', 'published', now(), '2026-10-23', array['KZ']::text[]);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'UZ', '{"original":"El-Yurt Umidi Foundation scholarships","en":"El-Yurt Umidi Foundation scholarships","ru":"Стипендии фонда «Эл-юрт умиди»"}'::jsonb, 'full', '{"en":"El-Yurt Umidi Foundation (Uzbekistan)","ru":"Фонд «Эл-юрт умиди» (Узбекистан)"}'::jsonb, array['bachelor', 'master', 'phd']::text[], '{"en":"Only for citizens of Uzbekistan studying abroad (bachelor''s, master''s and doctoral level). The funding can cover tuition, accommodation, meals, travel once a year each way, textbooks and medical insurance. Check the official site for the current admission period.","ru":"Только для граждан Узбекистана, которые учатся за границей (бакалавриат, магистратура, докторантура). Финансирование может покрывать обучение, проживание, питание, дорогу раз в год в обе стороны, учебники и медицинскую страховку. Сроки приёма — на официальном сайте."}'::jsonb, 'https://admission.eyuf.uz/', 'published', now(), '2026-10-23', array['UZ']::text[]);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'CZ', '{"original":"Czech Government Scholarships (development cooperation)","en":"Czech Government Scholarships (development cooperation)","ru":"Стипендии правительства Чехии (программа содействия развитию)"}'::jsonb, null, '{"en":"Ministry of Education and Ministry of Foreign Affairs of the Czech Republic","ru":"Министерство образования и Министерство иностранных дел Чехии"}'::jsonb, array['master', 'phd']::text[], '{"en":"For citizens of selected developing countries (not EU citizens and not residents of the Czech Republic); English-taught follow-up master''s and doctoral programmes. The list of countries changes with each call: the list used here is the call for 2027/2028, check the official page for the current one.","ru":"Для граждан отдельных развивающихся стран (не граждан ЕС и не жителей Чехии); магистратура (вторая ступень) и докторантура на английском. Список стран меняется с каждым конкурсом: использован список конкурса на 2027/2028, актуальный — на официальной странице."}'::jsonb, 'https://studyin.gov.cz/en/scholarships/scholarship-detail/?id=339', 'published', now(), '2026-10-23', array['BA', 'GE', 'UA', 'ET', 'GA', 'MR', 'ZM', 'BD', 'KH', 'PS', 'GT', 'HN']::text[]);
insert into public.scholarships (scope, host_country, names, covers, funder, levels, eligibility, url, status, verified_at, accessed_at, eligible_countries) values ('country', 'SE', '{"original":"Swedish Institute Scholarships for Global Professionals","en":"Swedish Institute Scholarships for Global Professionals","ru":"Стипендии Шведского института для глобальных специалистов"}'::jsonb, 'full', '{"en":"Swedish Institute","ru":"Шведский институт"}'::jsonb, array['master']::text[], '{"en":"Fully funded master''s studies in Sweden for citizens of the eligible countries (about 34; the list is on the official page). Work experience and leadership are required.","ru":"Полностью оплачиваемая магистратура в Швеции для граждан стран из списка (около 34; список — на официальной странице). Нужен опыт работы и лидерские качества."}'::jsonb, 'https://si.se/en/apply/scholarships/swedish-institute-scholarships-for-global-professionals/', 'published', now(), '2026-10-23', null);
